package com.steadyme.app.ui;
import android.content.Intent; import android.os.Bundle; import android.view.*; import androidx.annotation.*; import androidx.fragment.app.Fragment; import androidx.recyclerview.widget.LinearLayoutManager; import com.google.firebase.auth.FirebaseAuth; import com.google.firebase.firestore.ListenerRegistration; import com.google.android.material.snackbar.Snackbar; import com.steadyme.app.LoginActivity; import com.steadyme.app.data.FirebaseRepository; import com.steadyme.app.databinding.FragmentHomeBinding;
public class HomeFragment extends Fragment {private FragmentHomeBinding binding;private ListenerRegistration registration;private final FirebaseRepository repo=new FirebaseRepository();private final MoodLogAdapter adapter=new MoodLogAdapter();
 @Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle s){binding=FragmentHomeBinding.inflate(i,c,false);return binding.getRoot();}
 @Override public void onViewCreated(@NonNull View v,@Nullable Bundle s){super.onViewCreated(v,s);binding.rvRecent.setLayoutManager(new LinearLayoutManager(requireContext()));binding.rvRecent.setAdapter(adapter);String email=FirebaseAuth.getInstance().getCurrentUser()==null?"there":FirebaseAuth.getInstance().getCurrentUser().getEmail();binding.tvGreetingName.setText(email==null?"there 👋":email.split("@")[0]+" 👋");binding.tvLogout.setOnClickListener(x->logout());registration=repo.observeMoodLogs(new FirebaseRepository.LogsCallback(){public void onLoaded(java.util.List<com.steadyme.app.model.MoodLog> logs){adapter.submit(logs);binding.tvStreakValue.setText(String.valueOf(calculateStreak(logs)));binding.progressStreak.setProgress(Math.min(7,calculateStreak(logs)));}public void onError(Exception e){Snackbar.make(binding.getRoot(),e.getMessage(),Snackbar.LENGTH_LONG).show();}});}
 private void logout(){FirebaseAuth.getInstance().signOut();Intent intent=new Intent(requireContext(),LoginActivity.class);intent.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);startActivity(intent);}
 private int calculateStreak(java.util.List<com.steadyme.app.model.MoodLog> logs){return logs.size();} @Override public void onDestroyView(){if(registration!=null)registration.remove();binding=null;super.onDestroyView();}}
